 async function load(){const ticket=++sequence;controller?.abort();controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);$('status').textContent=tr('loading');$('error').hidden=true;try{const result=await live.catalog({search:$('query').value,category:$('category').value,store,page},controller.signal);if(ticket!==sequence)return;listing=result.products;renderProducts();$('page').textContent=String(page);$('previous').disabled=page===1;$('next').hidden=!result.hasNext;const q={lang};if(view==='cart')q.view='cart';if($('query').value)q.q=$('query').value;if($('category').value)q.category=$('category').value;if(store)q.store=store;history.replaceState(null,'',location.pathname+'?'+new URLSearchParams(q));}catch(e){if(ticket===sequence){listing=[];$('products').replaceChildren();error(e);}}finally{clearTimeout(timeout);if(ticket===sequence)$('status').textContent='';}}
 function renderQuote(){if(!quote)return;$('quoteDetails').replaceChildren();for(const s of quote.snapshot.stores){const row=node('div',undefined,'quote-store');row.append(node('h3',s.store_title));const list=node('ul');for(const item of quote.snapshot.items.filter(i=>i.store_id===s.store_id))list.append(node('li',item.title+' / '+item.variant_label+' × '+item.quantity+' — '+live.money(item.unit_price_minor*item.quantity,quote.snapshot.currency,lang)));row.append(list,node('p',tr('delivery')+': '+live.money(s.delivery_fee_minor,quote.snapshot.currency,lang)),node('strong',tr('total')+': '+live.money(s.items_minor+s.delivery_fee_minor,quote.snapshot.currency,lang)));$('quoteDetails').append(row);}$('quoteTotal').replaceChildren(node('span',tr('grandTotal')),node('strong',live.money(quote.snapshot.total_minor??quote.snapshot.stores.reduce((sum,s)=>sum+s.items_minor+s.delivery_fee_minor,0),quote.snapshot.currency,lang)));$('quoteExpiry').textContent=(lang==='ar'?'صالح حتى: ':'Valid until: ')+new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short'}).format(new Date(quote.expires_at));$('checkout').hidden=false;}
 async function privateCall(name,args,requestScope,ticket){const r=await requestScope.request(name,args);if(ticket!==epoch)throw {code:'SESSION_CHANGED'};if(r.error)throw r.error;return r.data;}
 $('quoteButton').addEventListener('click',async()=>{if(!ready||busy||pending)return;const ticket=epoch,revision=cartRevision;busy=true;renderCart();$('error').hidden=true;scope=api.orderScope();try{const nextQuote=await privateCall('bemo_quote_cart',{cart:live.cart().map(({variant_id,quantity})=>({variant_id,quantity}))},scope,ticket);if(revision!==cartRevision)return;quote=nextQuote;setView('cart');renderQuote();$('checkout').scrollIntoView({block:'start'});}catch(e){if(ticket===epoch)error(e);}finally{if(ticket===epoch){busy=false;renderCart();}}});
 $('deliveryForm').addEventListener('submit',async event=>{event.preventDefault();if(!ready||busy||!quote||!scope||!$('confirmQuote').checked)return;const ticket=epoch;busy=true;$('placeButton').disabled=true;$('error').hidden=true;const delivery={};for(const key of ['recipient','phone','country','region','city','address','note'])delivery[key]=$(key).value.trim();if(!pending&&(!/^\+?[0-9 ()-]{7,25}$/.test(delivery.phone)||delivery.recipient.length<2||delivery.country.length<2||!delivery.region||!delivery.city||delivery.address.length<8)){busy=false;$('placeButton').disabled=false;error();return;}pending=pending||{quote_id:quote.id,delivery,request_id:crypto.randomUUID()};document.querySelectorAll('#deliveryForm input,#deliveryForm textarea').forEach(n=>n.disabled=true);renderCart();try{const order=await privateCall('bemo_place_order',pending,scope,ticket);resetQuote();live.clear();$('success').hidden=false;$('orderReference').textContent=order.id;$('success').scrollIntoView({block:'start'});}catch(e){if(ticket===epoch){if(['QUOTE_CHANGED','QUOTE_EXPIRED','ITEM_UNAVAILABLE','STOCK_INSUFFICIENT','MIXED_CURRENCY'].includes(e.code)){resetQuote();error(e);}else error({code:e.code==='NETWORK_ERROR'?'uncertain':e.code});}}finally{if(ticket===epoch){busy=false;$('placeButton').disabled=false;renderCart();}}});
 $('browseView').addEventListener('click',()=>setView('browse',true));$('cartView').addEventListener('click',()=>setView('cart',true));
 $('searchForm').addEventListener('submit',e=>{e.preventDefault();setView('browse');page=1;load();});$('previous').addEventListener('click',()=>{if(page>1){page--;load();}});$('next').addEventListener('click',()=>{if(page<834){page++;load();}});$('languageButton').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';language();renderProducts();renderCart();renderQuote();});window.addEventListener('bemo:cart',()=>{cartRevision++;if(!pending)resetQuote();renderCart();});
 $('query').value=params.get('q')||'';$('category').value=live.categories.includes(params.get('category'))?params.get('category'):'';language();renderCart();load();
 if(api){api.subscribe(s=>{const id=s.phase==='ready'?s.profile?.id:null;if(id!==actor||s.phase!=='ready'){const old=actor;epoch++;actor=id;busy=false;resetQuote();$('success').hidden=true;$('orderReference').textContent='';$('placeButton').disabled=false;if(old&&old!==id)live.clear();}ready=s.phase==='ready'&&Boolean(id);renderCart();});api.initialize();}
